<?php
require_once __DIR__.'/config/auth.php';require_staff();require_once __DIR__.'/config/pedidos.php';
$db=getDBConnection();$error='';$success=$_SESSION['av_order_success']??'';unset($_SESSION['av_order_success']);
$labels=['pendiente_pago'=>'Pendiente de pago','pendiente_verificacion'=>'Verificar pago','pagado_verificado'=>'Pago verificado','preparando'=>'En preparación','listo_retiro'=>'Listo para retirar','completado'=>'Completado','cancelado'=>'Cancelado','pendiente'=>'Pendiente','procesando'=>'En proceso'];
$next=['pagado_verificado'=>'preparando','preparando'=>'listo_retiro','listo_retiro'=>'completado'];
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST')try{
 $db->beginTransaction();$q=$db->prepare('SELECT * FROM pedidos WHERE id=? FOR UPDATE');$q->execute([(int)($_POST['id']??0)]);$o=$q->fetch();if(!$o)throw new RuntimeException('Pedido no encontrado.');$action=$_POST['accion']??'';$user=auth_user_id();
 if($action==='cobrar'){
  if(!in_array(auth_current_role(),['admin','veterinarian'],true))throw new RuntimeException('Solo administración o veterinario puede confirmar cobros.');
  if($o['metodo_pago']!=='efectivo'||!in_array($o['estado'],['pendiente_pago','pendiente'],true)||$o['factura_id'])throw new RuntimeException('El pedido no admite este cobro.');
  av_order_stock($db,$o,$user);av_order_invoice($db,$o,$user);
  $db->prepare("INSERT INTO pagos(pedido_id,cliente_id,metodo_pago,monto,fecha_pago,estado,verificado_por,fecha_verificacion) VALUES(?,?,'efectivo',?,CURDATE(),'verificado',?,NOW())")->execute([$o['id'],$o['cliente_id'],$o['total'],$user]);$pid=$db->lastInsertId();
  $db->prepare("UPDATE pedidos SET pago_id=?,estado='pagado_verificado',verificado_por=?,fecha_verificacion_pago=NOW() WHERE id=?")->execute([$pid,$user,$o['id']]);$message='Cobro en efectivo registrado.';
 }elseif($action==='avanzar'){
  $state=$next[$o['estado']]??null;if(!$state||($next[$o['estado']]??'')!==($_POST['estado']??''))throw new RuntimeException('La transición de estado ya no es válida. Recargue la página.');
  $db->prepare('UPDATE pedidos SET estado=? WHERE id=?')->execute([$state,$o['id']]);$message='Estado: '.$labels[$state];
 }elseif($action==='cancelar'){
  $reason=trim($_POST['motivo']??'');if(!$reason)throw new RuntimeException('Indique el motivo de cancelación.');
  if(!in_array($o['estado'],['pendiente_pago','pendiente_verificacion','pendiente'],true)||$o['factura_id'])throw new RuntimeException('Solo se puede cancelar un pedido pendiente sin cobro.');
  if($o['stock_reservado']){$q=$db->prepare('SELECT * FROM pedido_detalles WHERE pedido_id=? ORDER BY producto_id');$q->execute([$o['id']]);foreach($q->fetchAll() as $d)av_stock($db,(int)$d['producto_id'],(int)$d['cantidad'],'Cancelación pedido #'.$o['numero_pedido'],$user);}
  $db->prepare("UPDATE pedidos SET estado='cancelado',stock_reservado=0 WHERE id=?")->execute([$o['id']]);$db->prepare("UPDATE pagos SET estado='rechazado',motivo_rechazo=? WHERE pedido_id=? AND estado='pendiente'")->execute([$reason,$o['id']]);$message='Pedido cancelado: '.$reason;
 }else throw new RuntimeException('Acción no válida.');
 av_order_log($db,$o,$user,$action,$message);$db->commit();$_SESSION['av_order_success']=$message;header('Location: pedidos_admin.php?id='.$o['id']);exit;
}catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log('[pedidos] '.$e->getMessage());$error=$e instanceof PDOException?'No se pudo actualizar el pedido.':$e->getMessage();}
$id=(int)($_GET['id']??0);$search=trim($_GET['buscar']??'');$page=max(1,(int)($_GET['pagina']??1));$offset=($page-1)*40;
$q=$db->prepare("SELECT p.*,c.nombre FROM pedidos p JOIN clientes c ON c.id=p.cliente_id WHERE (?=0 OR p.id=?) AND (p.numero_pedido LIKE ? OR c.nombre LIKE ?) ORDER BY p.id DESC LIMIT 40 OFFSET $offset");$q->execute([$id,$id,'%'.$search.'%','%'.$search.'%']);$orders=$q->fetchAll();
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pedidos · VetNexo</title><?php av_head();?></head><body><?php include __DIR__.'/sidebar.php';?><main class="av-page"><h1>Pedidos</h1><p>Controle pagos, preparación, entrega y cancelaciones.</p><?php if($error):?><p class="av-error"><?=e($error)?></p><?php endif;?><?php if($success):?><p class="av-success"><?=e($success)?></p><?php endif;?><form class="av-card" method="get"><label>Buscar por pedido o cliente</label><input name="buscar" value="<?=e($search)?>"><button>Buscar</button> <a href="pedidos_admin.php">Ver todos</a> · <a href="verificar_pagos.php">Verificar comprobantes</a></form>
<?php foreach($orders as $o):?><article class="av-card"><h2><?=e($o['numero_pedido'])?> · <?=e($labels[$o['estado']]??$o['estado'])?></h2><p><?=e($o['nombre'])?> · USD <?=number_format((float)$o['total'],2)?> · <?=e($o['metodo_pago'])?></p><p><?=e($o['direccion_envio'])?> · <?=e($o['telefono_contacto'])?></p><details><summary>Productos</summary><table><thead><tr><th>Producto</th><th>Cantidad</th><th>Subtotal USD</th></tr></thead><tbody><?php $q=$db->prepare('SELECT d.*,p.nombre FROM pedido_detalles d JOIN productos p ON p.id=d.producto_id WHERE d.pedido_id=?');$q->execute([$o['id']]);foreach($q as $d):?><tr><td><?=e($d['nombre'])?></td><td><?=e($d['cantidad'])?></td><td><?=e($d['subtotal'])?></td></tr><?php endforeach;?></tbody></table></details>
<?php if($o['factura_id']):?><p><a href="ver_factura.php?id=<?=(int)$o['factura_id']?>">Ver factura</a></p><?php endif;?>
<?php if($o['pago_id']):?><p><a href="verificar_pago.php?id=<?=(int)$o['pago_id']?>">Ver comprobante / pago</a></p><?php endif;?>
<?php if(isset($next[$o['estado']])):?><form method="post"><?=av_csrf_field()?><input type="hidden" name="id" value="<?=(int)$o['id']?>"><input type="hidden" name="accion" value="avanzar"><input type="hidden" name="estado" value="<?=e($next[$o['estado']])?>"><button>Marcar: <?=e($labels[$next[$o['estado']]])?></button></form><?php endif;?>
<?php if(in_array($o['estado'],['pendiente_pago','pendiente','pendiente_verificacion'],true)&&!$o['factura_id']):?>
<?php if($o['metodo_pago']==='efectivo'&&in_array(auth_current_role(),['admin','veterinarian'],true)):?><form method="post" onsubmit="return confirm('¿Confirma que recibió el total en efectivo?')"><?=av_csrf_field()?><input type="hidden" name="id" value="<?=(int)$o['id']?>"><button name="accion" value="cobrar">Confirmar cobro en efectivo</button></form><?php endif;?>
<details><summary>Cancelar pedido pendiente</summary><form method="post" onsubmit="return confirm('¿Cancelar y devolver las existencias reservadas?')"><?=av_csrf_field()?><input type="hidden" name="id" value="<?=(int)$o['id']?>"><label>Motivo</label><input name="motivo" required maxlength="500"><button name="accion" value="cancelar">Cancelar pedido</button></form></details><?php endif;?></article><?php endforeach;?>
<?php if(!$orders):?><p>No se encontraron pedidos.</p><?php endif;?><?php if(!$id):?><p><?php if($page>1):?><a href="?pagina=<?=$page-1?>&buscar=<?=urlencode($search)?>">Anterior</a> · <?php endif;?>Página <?=$page?><?php if(count($orders)===40):?> · <a href="?pagina=<?=$page+1?>&buscar=<?=urlencode($search)?>">Siguiente</a><?php endif;?></p><?php endif;?></main></body></html>
